// This file is generated by AI.

// 数值参数输入框: [−] 输入框 [+]
//
// 合成参数一律用数字输入框而不是滑杆:
// * 滑杆**看不到当前值**, 也没法精确输入 —— 而温度 1.05 与 1.10 的差别是听得出来的;
// * 滑杆占一整行, 数字框可以并排, 面板因此能在固定高度里放下全部参数。
//
// 两侧的加减按钮按 `tick.step` 走一格 (温度/语速 0.05, topK 1), 到边界即禁用。
// 取值范围写在字段标签上 (见 `SentenceVoicePanel`), 不塞进输入框 —— 输入框要留给
// 数值本身和两个按钮。
//
// 输入过程中不校验 (允许暂时为空、暂时越界), 失焦或回车时才夹到 `tick` 的范围内,
// 因此不会出现"删到一半就被弹回原值"。

import { Button, Input } from '@fluentui/react-components';
import { AddRegular, SubtractRegular } from '@fluentui/react-icons';
import { useEffect, useState } from 'react';

export interface NumberTick {
  min: number;
  max: number;
  step: number;
  default: number;
}

interface Props {
  value: number;
  tick: NumberTick;
  /** 只接受整数 (topK / 种子) */
  integer?: boolean;
  disabled?: boolean;
  onCommit: (value: number) => void;
}

/** 小数位: 由步长决定 (0.05 -> 两位), 整数参数为 0 位 */
function decimalsOf(tick: NumberTick, integer: boolean | undefined): number {
  if (integer) return 0;
  const text = String(tick.step);
  const dot = text.indexOf('.');
  return dot < 0 ? 0 : text.length - dot - 1;
}

export function NumberInput({ value, tick, integer, disabled, onCommit }: Props) {
  const decimals = decimalsOf(tick, integer);
  const [text, setText] = useState(value.toFixed(decimals));

  // 外部值变化 (切换语句 / 换角色) 时同步显示
  useEffect(() => {
    setText(value.toFixed(decimals));
  }, [value, decimals]);

  /** 落定一个数值: 夹到范围内, 回写显示, 与当前值不同才上报 */
  const apply = (raw: number) => {
    if (!Number.isFinite(raw)) {
      setText(value.toFixed(decimals));
      return;
    }
    const clamped = Math.min(tick.max, Math.max(tick.min, integer ? Math.round(raw) : raw));
    setText(clamped.toFixed(decimals));
    if (clamped !== value) onCommit(clamped);
  };

  const commit = () => apply(Number.parseFloat(text));

  /** 加减一格; 先按小数位取整, 免得 1 - 0.05 变成 0.9500000000000001 */
  const nudge = (direction: 1 | -1) => {
    apply(Number((value + direction * tick.step).toFixed(decimals)));
  };

  return (
    <div className="voice-number">
      <Button
        className="voice-number-step"
        size="small"
        appearance="subtle"
        icon={<SubtractRegular />}
        title={`减 ${tick.step}`}
        disabled={disabled || value <= tick.min}
        onClick={() => nudge(-1)}
      />
      <Input
        className="voice-control"
        value={text}
        disabled={disabled}
        inputMode="decimal"
        title={`${tick.min} ~ ${tick.max}，步长 ${tick.step}`}
        onChange={(_, data) => setText(data.value)}
        onBlur={commit}
        onKeyDown={(event) => {
          if (event.key === 'Enter') {
            commit();
            (event.target as HTMLInputElement).blur();
          }
        }}
      />
      <Button
        className="voice-number-step"
        size="small"
        appearance="subtle"
        icon={<AddRegular />}
        title={`加 ${tick.step}`}
        disabled={disabled || value >= tick.max}
        onClick={() => nudge(1)}
      />
    </div>
  );
}
